      const correlacion = pm.response.headers.get("X-Correlation-Id");
      pm.test("D-26 X-Correlation-Id es un UUID v7 en minúsculas", () => pm.expect(correlacion).to.match(UUID_V7));
      pm.test("D-26 X-Correlation-Id no se repite entre respuestas", () => {
        const vistos = JSON.parse(pm.collectionVariables.get("correlacionesVistas") || "[]");
        pm.expect(vistos).to.not.include(correlacion);
        pm.collectionVariables.set("correlacionesVistas", JSON.stringify(vistos.concat(correlacion)));
      });
